WITH exploded AS (SELECT id, host, log_ts, level, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, value), flattened_attrs AS (SELECT id, log_ts, level, attr_key, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS is_flagged FROM exploded), matched_keys AS (SELECT level, id FROM flattened_attrs EXCEPT SELECT level, id FROM app_logs WHERE log_ts < '2025-04-01'), verified AS (SELECT s.* FROM flattened_attrs s INNER JOIN matched_keys k ON s.level = k.level AND s.id = k.id), enriched AS (SELECT *, RANK() OVER w_running AS status_code_high_rank FROM verified WINDOW w_running AS (PARTITION BY YEAR(log_ts), level ORDER BY status_code_high NULLS LAST)), base AS (SELECT id, log_ts, level, attr_key, status_code_high, is_flagged, CONCAT_WS('-', attr_key, level) AS attr_key_level_key, GREATEST(status_code_high, is_flagged) AS greatest_status_code_high_is_flagged FROM enriched WHERE log_ts > TIMESTAMP '2025-06-01 08:00:00' AND level IN ('ERROR', 'WARN')) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, COUNT(*) FILTER (WHERE attr_key = 'version') AS version_rows, COUNT(*) AS row_count, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list, MIN(log_ts) AS first_seen, GROUPING_ID() AS grouping_id FROM base GROUP BY CUBE (DATE_TRUNC('DAY', log_ts))
